import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { validateVendorProfileForm, getErrorMessage } from '../../utils/helpers';
import { OPERATING_REGIONS, SUCCESS_MESSAGES } from '../../utils/constants';

const VendorProfile = () => {
  const [formData, setFormData] = useState({
    name: '',
    cuisineSpecialties: '',
    operatingRegion: '',
    menuHighlights: '',
    phoneNumber: '',
    businessAddress: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [message, setMessage] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  
  const navigate = useNavigate();

  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    try {
      setInitialLoading(true);
      const response = await vendorService.getProfile();
      setFormData(response.data);
      setIsEditing(true);
    } catch (error) {
      // Profile doesn't exist yet - that's okay for new vendors
      if (error.response?.status !== 404) {
        console.error('Error loading profile:', getErrorMessage(error));
      }
    } finally {
      setInitialLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    const validationErrors = validateVendorProfileForm(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setLoading(true);
    setMessage('');
    setErrors({});

    try {
      await vendorService.createOrUpdateProfile(formData);
      setMessage(isEditing ? SUCCESS_MESSAGES.PROFILE_UPDATED : SUCCESS_MESSAGES.PROFILE_CREATED);
      setIsEditing(true);
      
      // Redirect to dashboard after success
      setTimeout(() => {
        navigate('/vendor-dashboard');
      }, 2000);
    } catch (error) {
      const errorMessage = getErrorMessage(error);
      setErrors({ general: errorMessage });
    } finally {
      setLoading(false);
    }
  };

  if (initialLoading) {
    return <LoadingSpinner message="Loading your profile..." />;
  }

  return (
    <div className="vendor-profile-page">
      <div className="container">
        <div className="page-header">
          <h1>{isEditing ? 'Edit Your Profile' : 'Create Your Profile'}</h1>
          <p>Complete your business information to start accepting applications</p>
        </div>

        {message && <div className="success-message">{message}</div>}
        {errors.general && <div className="error-message">{errors.general}</div>}

        <form onSubmit={handleSubmit} className="profile-form">
          <div className="form-section">
            <h3>Business Information</h3>
            
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="name">Business Name *</label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className={errors.name ? 'error' : ''}
                  placeholder="Enter your food truck name"
                />
                {errors.name && <span className="error-text">{errors.name}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="phoneNumber">Phone Number *</label>
                <input
                  type="tel"
                  id="phoneNumber"
                  name="phoneNumber"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  className={errors.phoneNumber ? 'error' : ''}
                  placeholder="Enter your contact number"
                />
                {errors.phoneNumber && <span className="error-text">{errors.phoneNumber}</span>}
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="businessAddress">Business Address *</label>
              <textarea
                id="businessAddress"
                name="businessAddress"
                value={formData.businessAddress}
                onChange={handleChange}
                className={errors.businessAddress ? 'error' : ''}
                placeholder="Enter your business address"
                rows="3"
              />
              {errors.businessAddress && <span className="error-text">{errors.businessAddress}</span>}
            </div>
          </div>

          <div className="form-section">
            <h3>Food & Service Information</h3>
            
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="cuisineSpecialties">Cuisine Specialties *</label>
                <input
                  type="text"
                  id="cuisineSpecialties"
                  name="cuisineSpecialties"
                  value={formData.cuisineSpecialties}
                  onChange={handleChange}
                  className={errors.cuisineSpecialties ? 'error' : ''}
                  placeholder="e.g., Indian, Chinese, Italian"
                />
                {errors.cuisineSpecialties && <span className="error-text">{errors.cuisineSpecialties}</span>}
                <small className="form-help">Separate multiple cuisines with commas</small>
              </div>

              <div className="form-group">
                <label htmlFor="operatingRegion">Operating Region *</label>
                <select
                  id="operatingRegion"
                  name="operatingRegion"
                  value={formData.operatingRegion}
                  onChange={handleChange}
                  className={errors.operatingRegion ? 'error' : ''}
                >
                  <option value="">Select a region</option>
                  {OPERATING_REGIONS.map(region => (
                    <option key={region} value={region}>{region}</option>
                  ))}
                </select>
                {errors.operatingRegion && <span className="error-text">{errors.operatingRegion}</span>}
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="menuHighlights">Menu Highlights</label>
              <textarea
                id="menuHighlights"
                name="menuHighlights"
                value={formData.menuHighlights}
                onChange={handleChange}
                placeholder="Describe your signature dishes and specialties"
                rows="4"
              />
              <small className="form-help">Tell customers about your best dishes (optional)</small>
            </div>
          </div>

          <div className="form-actions">
            <button 
              type="button" 
              onClick={() => navigate('/vendor-dashboard')}
              className="btn btn-outline"
            >
              Cancel
            </button>
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? 'Saving...' : (isEditing ? 'Update Profile' : 'Create Profile')}
            </button>
          </div>
        </form>

        {loading && <LoadingSpinner message="Saving your profile..." />}
      </div>
    </div>
  );
};

export default VendorProfile;
